import pathlib,json,zipfile,hashlib,datetime
ROOT=pathlib.Path(__file__).resolve().parents[1]
def main():
 for d in ['src','scripts','configs','tests','outputs/logs','outputs/checkpoints','outputs/figures']:(ROOT/d).mkdir(parents=True,exist_ok=True)
 with zipfile.ZipFile(ROOT/'official_worldts_source.zip') as z:
  for n in z.namelist():
   if not n.startswith('upstream/WorldTS/') or n.endswith('/'):continue
   rel=pathlib.PurePosixPath(n);assert '..' not in rel.parts;p=ROOT/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(z.read(n))
 source=json.loads((ROOT/'configs/source_manifest.json').read_text())
 for r in source:assert hashlib.sha256((ROOT/r['path']).read_bytes()).hexdigest()==r['sha256']
 # Conservative raw-support embargo: there are1079 genuinely unused raw hours between sets.
 select_first=36690;select_last=38051;diagnostic_first=40210;diagnostic_last=41572
 assert diagnostic_first-720-(select_last+359)-1==1079
 protocol={'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_commit':'269426ea6217d7152a244da0e209d922acd46d4f','repository_parent':'13c195ff0b791794b9722baae1910f3b51645f88','tasks':['NP','PJM'],'seed':2021,'T':720,'H':360,'stage1_epochs':6,'stage1_training':'official Adam lr0.001/type3/batch32/drop_last=True/shuffle=True; only snapshot capture and no early termination changed; original full-validation shuffle is retained during Stage1 replay','stage1_selection_epochs':[1,3,6],'stage2_epochs':20,'stage2_training':'official Adam NP1e-4/PJM2e-4,type3,batch32,shuffleTrue,drop_lastTrue; no early stopping; all1112updates/epoch,20epochs','stage2_objective':'predicted-state MAE +0.3 target-state reconstruction MAE','stage2_checkpoint_selection':'fixed chronological V_select; official unweighted batch-mean MAE, Step0 eligible; float64 full element-weighted MAE/MSE also saved','stage2_rng':'seed2021 reset immediately before each20epoch fit; identical task-specific untrained Decoder weights and shuffle/dropout RNG; V_select evaluation consumes no RNG','validation_origins_all':[36690,41572],'V_select_origins':[select_first,select_last],'V_diagnostic_origins':[diagnostic_first,diagnostic_last],'raw_support_embargo_hours':1079,'origin_range_embargo_hours':2158,'V_diagnostic_policy':'only evaluate after all six Decoder fits and checkpoint selections are final; never used for training/checkpoint selection or hyperparameters; historical full-validation exposure disclosed','train_probe':'4883 evenly spaced TRAIN origins from720 through36330, same tail batch19 and32 batch size as full validation; deterministic chronological grouping','partition_seeds':[91001,91002,91003,91004,91005],'partition_primary':'chronological all4883 validation origins, unchanged full objective and original unweighted batch means; exclude batch regularizer only as separate diagnostic','geometry_origins':'16 evenly spaced TRAIN and16 evenly spaced full-validation origins; predefined, diagnostic only','geometry_epochs':[1,3,6],'geometry':'centered linear CKA plus explicitly uncentered linear kernel alignment; training-fit centered orthogonal Procrustes toEpoch1, eval validation only; no deployment mapping','effective_rank':'exp entropy of normalized singular values of centered token matrix; covariance participation ratio separately reported','bootstrap_block_lengths':[360,720,1080],'bootstrap_repetitions':2000,'bootstrap_seed':92021,'meaningful_effect_mae_fraction':0.02,'decision_rules':{'state_selection':'Epoch1 primary latent best; later snapshot decoder >2percent gain vsEpoch1 and best other snapshot, same20epoch and fixed-update opportunities, positive time-block tendency and coherent two-task evidence or explicit testable task difference; gains are exploratory diagnostics','generalization_optimization':'later snapshots degrade both matched eval latent loss and matched-budget forecasting; mechanism not uniquely identified by this audit','no_go':'protocol artifact, small downstream differences, unequal-budget explanation or incoherent task pattern','inconclusive':'insufficient block information, nonconvergence, inconclusive task differences; no novel mechanism invented'},'test_policy':'no Test predictions, scores or selection in this new experiment; inputs scalers/original source verified read-only','no_new_method':True}
 p=ROOT/'configs/protocol.json'
 if p.is_file():
  old=json.loads(p.read_text());a=dict(old);b=dict(protocol);a.pop('created_utc');b.pop('created_utc');assert a==b
 else:p.write_text(json.dumps(protocol,indent=2),encoding='utf-8')
 print('BOOTSTRAP_SOURCE_PROTOCOL_VERIFIED',len(source),flush=True)
if __name__=='__main__':main()
